 private static void bay(Minecraft m){var p=NativeNavigationClientFixture.TABLE;need(m.player.getInventory().selected==0&&m.gameMode.getPlayerMode()==GameType.SURVIVAL,"client Survival/main-slot synchronized");m.gameMode.useItemOn(m.player,InteractionHand.MAIN_HAND,new BlockHitResult(new Vec3(p.getX()+.5,p.getY()+.23,p.getZ()+1),Direction.SOUTH,p,false));}
 @SubscribeEvent public static void tick(ClientTickEvent.Post event){if(!NativeNavigationClientFixture.enabled())return;var m=Minecraft.getInstance();if(m.screen instanceof net.minecraft.client.gui.screens.AccessibilityOnboardingScreen intro){intro.onClose();return;}if(stage==9&&m.level==null){System.out.println("[vandorlabs][navigation-client] client PASS realSurvival/moduleInsertExtract/angledButtonRay/nativeRaster/pin/player/haiku/tableScreen/fixedPixels/sourceMeshes");m.stop();next(10);return;}need(!(m.screen instanceof net.minecraft.client.gui.screens.DisconnectedScreen),"unexpected disconnect");if(m.level==null||m.player==null||m.gameMode==null)return;need(++ticks<2400&&++stageTicks<500,"timeout held="+m.player.getMainHandItem()+" mode="+m.gameMode.getPlayerMode()+" pos="+m.player.position()+" gui="+m.screen);if(stageTicks%100==0)System.out.println("[vandorlabs][navigation-client] progress stage="+stage+" ticks="+stageTicks+" held="+m.player.getMainHandItem());m.getToasts().clear();m.gui.getChat().clearMessages(true);var t=table(m);
  if(t!=null&&t.reader()!=null&&!refinementSeen)observeRefinement(t.reader());
  switch(stage){case 0->{if(!ack(m,0)||t==null||!t.formed()||!t.hasModuleBay()||m.gameMode.getPlayerMode()!=GameType.SURVIVAL||!m.player.getMainHandItem().is(NativeNavigationItems.MODULE)||m.player.position().distanceToSqr(.5,96,5.5)>.01)return;models(m);bay(m);next(1);}case 1->{if(t.moduleStack().isEmpty()||!m.player.getMainHandItem().isEmpty()||NativeNavigationModuleData.count(t.moduleStack())==0)return;var owner=t.reader();var image=NativeNavigationClient.image(owner.getBlockPos(),0);if(image==null||image.empty()||!image.pin()||!refinementSeen)return;need(image.columns()>0,"real nonempty native map raster received");carriedTray(m,t);need(t.canvas().width>300&&t.canvas().count==8,"joined table fixed physical pixels+WRITE");mode(0);capture="map-and-module";next(2);}case 2->{if(!ack(m,1)||capture!=null)return;if(NativeNavigationClientFixture.fullBay()){if(!m.player.getMainHandItem().is(NativeNavigationItems.MODULE))return;bay(m);next(20);}else{bay(m);next(3);}}case 20->{if(stageTicks<8)return;need(!t.moduleStack().isEmpty()&&m.player.getMainHandItem().is(NativeNavigationItems.MODULE)&&m.player.getMainHandItem().getCount()==1&&m.screen==null,"full bay rejected insertion must not extract existing module or consume held cassette");mode(10);next(21);}case 21->{if(!ack(m,5)||!m.player.getMainHandItem().isEmpty())return;bay(m);next(3);}case 3->{if(!t.moduleStack().isEmpty()||!m.player.getMainHandItem().is(NativeNavigationItems.MODULE))return;zoom=NativeNavigationClient.image(t.reader().getBlockPos(),0).zoom();mode(1);next(4);}case 4->{if(!ack(m,2)||!m.player.getMainHandItem().isEmpty()||stageTicks<8)return;m.gameRenderer.pick(1);need(m.hitResult instanceof BlockHitResult,"fresh table button block ray");var hit=(BlockHitResult)m.hitResult;need(m.level.getBlockEntity(hit.getBlockPos()) instanceof NativeNavigationTableEntity,"actual angled table ray target "+hit);m.gameMode.useItemOn(m.player,InteractionHand.MAIN_HAND,hit);capture="zoom-transition";next(5);}case 5->{var image=NativeNavigationClient.image(t.reader().getBlockPos(),0);if(image==null||image.zoom()==zoom)return;need(m.screen==null,"authored angled plane action consumed as map button");mode(2);next(6);}case 6->{if(!ack(m,3)||stageTicks<30)return;var h=m.level.getBlockEntity(NativeNavigationClientFixture.HAIKU);need(h instanceof NativeNavigationTableEntity,"haiku singleton");var image=NativeNavigationClient.image(NativeNavigationClientFixture.HAIKU,0);if(image==null||!image.unlinked())return;need(m.level.getBlockEntity(NativeNavigationClientFixture.SCREEN) instanceof NativeScreenEntity screen&&NativeScreenNavigation.selected(screen,0)&&NativeScreenNavigation.canvas(screen,0).count==7,"existing chip-capable screen Navigation excludes WRITE");capture="navigation-scene";next(7);}case 7->{if(capture!=null)return;mode(3);next(8);}case 8->{if(!ack(m,4))return;m.level.disconnect();m.disconnect();next(9);}default->{}}
 }
 private static void observeRefinement(NativeNavigationTableEntity table){
  var image=NativeNavigationClient.image(table.getBlockPos(),0);
  var canvas=table.canvas();
  if(image==null||image.pixels()==null||image.empty()||!canvas.canRefine(image.zoom()))return;
  if(image.columns()==canvas.gridWidth(image.zoom())&&image.rows()==canvas.gridHeight(image.zoom())){
   if(image!=preview){preview=image;previewAt=ticks;}
  }else if(preview!=null&&preview.x()==image.x()&&preview.z()==image.z()&&preview.zoom()==image.zoom()
          &&preview.width()==image.width()&&preview.height()==image.height()){
   need(image.revision()>preview.revision()&&image.columns()==canvas.gridWidth(image.zoom(),true)
           &&image.rows()==canvas.gridHeight(image.zoom(),true),"preview upgrades in place at twice the raster density");
   refinementSeen=true;
   System.out.println("[vandorlabs][navigation-client] refinement PASS "+preview.columns()+"x"+preview.rows()
           +" -> "+image.columns()+"x"+image.rows()+" client-ticks="+(ticks-previewAt));
   preview=null;
  }
 }
 @SubscribeEvent public static void frame(RenderFrameEvent.Post e)throws Exception{if(!NativeNavigationClientFixture.enabled()||capture==null)return;var m=Minecraft.getInstance();if(m.level==null||m.screen!=null||m.getOverlay()!=null||!drawn)return;var path=m.gameDirectory.toPath().resolve("screenshots/navigation-"+capture+".png");try(var image=net.minecraft.client.Screenshot.takeScreenshot(m.getMainRenderTarget())){java.nio.file.Files.createDirectories(path.getParent());image.writeToFile(path);int colored=0,cyan=0,gold=0,green=0;for(int y=0;y<image.getHeight()*4/5;y++)for(int x=image.getWidth()/5;x<image.getWidth()*4/5;x++){int c=image.getPixelRGBA(x,y),r=c&255,g=c>>>8&255,b=c>>>16&255;if(Math.max(r,Math.max(g,b))-Math.min(r,Math.min(g,b))>35)colored++;if(g>r+20&&g>b+20)green++;if(g>150&&b>150&&r<140)cyan++;if(r>150&&g>130&&b<140)gold++;}need(colored>300,"actual rendered colored map/source/controls framebuffer");if(!Boolean.getBoolean("vandorlabs.navigationFullBayNegative"))need(green>100,"actual framebuffer plains map keeps intended green palette instead of hurt-red overlay");int scale=(int)m.getWindow().getGuiScale();for(int index=0;index<3;index++){if(Boolean.getBoolean("vandorlabs.navigationFullBayNegative"))break;int ink=0;for(int py=0;py<16*scale;py++)for(int px=0;px<16*scale;px++){int color=image.getPixelRGBA((20+index*28)*scale+px,(m.getWindow().getGuiScaledHeight()-24)*scale+py)&0xffffff;if(color==0x302820)continue;ink++;need(px>=scale&&px<15*scale&&py>=scale&&py<15*scale,"actual inventory item padding "+index+" "+px+","+py);}need(ink>20,"visible native icon "+index);}System.out.println("[vandorlabs][navigation-client] capture "+capture+" PASS colored="+colored+" cyan="+cyan+" gold="+gold+" green="+green);}capture=null;drawn=false;}

 @SubscribeEvent public static void icons(RenderGuiEvent.Post event){if(!NativeNavigationClientFixture.enabled()||capture==null)return;var m=Minecraft.getInstance();var g=event.getGuiGraphics();var items=new net.minecraft.world.item.ItemStack[]{new net.minecraft.world.item.ItemStack(NativeNavigationTableBindings.FLAT),new net.minecraft.world.item.ItemStack(NativeNavigationTableBindings.ANGLED),new net.minecraft.world.item.ItemStack(NativeNavigationItems.MODULE)};int y=m.getWindow().getGuiScaledHeight()-28;for(int i=0;i<items.length;i++){int x=16+i*28;g.fill(x,y,x+24,y+24,0xff202830);g.renderItem(items[i],x+4,y+4);}g.flush();drawn=true;}

 private static void models(Minecraft m){com.vandorlabs.neoforge.navigation.observer.NativeObserverScaleRenderChecks.run();var t=table(m);var shell=m.getBlockRenderer().getBlockModel(t.getBlockState());var shellQuads=shell.getQuads(t.getBlockState(),null,net.minecraft.util.RandomSource.create(0));need(!shellQuads.isEmpty(),"native chunk-batched table shell");for(var quad:shellQuads)need(!quad.getSprite().contents().name().toString().contains("missingno"),"resolved table shell texture");for(var name:new String[]{"bay_frame","bay_module","chip_frame"}){var model=m.getModelManager().getModel(net.minecraft.client.resources.model.ModelResourceLocation.standalone(net.minecraft.resources.ResourceLocation.parse("vandorlabs:block/navigation_table/"+name)));var quads=new java.util.ArrayList<net.minecraft.client.renderer.block.model.BakedQuad>();var random=net.minecraft.util.RandomSource.create(0);quads.addAll(model.getQuads(null,null,random));for(var d:Direction.values())quads.addAll(model.getQuads(null,d,random));need(!quads.isEmpty(),"actual baked attachment "+name);for(var quad:quads){need(!quad.getSprite().contents().name().toString().contains("missingno"),"resolved attachment texture "+name);if(!name.equals("bay_frame"))continue;int[] words=quad.getVertices();int stride=words.length/4;for(var facing:Direction.Plane.HORIZONTAL){var transform=new org.joml.Matrix4f().translate(.5f,0,.5f).rotateY((float)Math.toRadians(-facing.toYRot()+180)).translate(-.5f,0,-.5f);for(int vertex=0;vertex<4;vertex++){int at=vertex*stride;var point=transform.transformPosition(Float.intBitsToFloat(words[at]),Float.intBitsToFloat(words[at+1]),Float.intBitsToFloat(words[at+2]),new org.joml.Vector3f());need(point.y>=1.74/16&&point.y<=5.76/16,"four-facing bay stays between foot and console plate");need(point.x>=-.01&&point.x<=1.01&&point.z>=-.01&&point.z<=1.01,"four-facing bay fits table recess");}}}}System.out.println("[vandorlabs][navigation-client] models PASS actualBakedAttachments/resolvedSprites/fourFacingBayRecess");}

 private static final class Sink implements com.mojang.blaze3d.vertex.VertexConsumer{int vertices;public com.mojang.blaze3d.vertex.VertexConsumer addVertex(float x,float y,float z){vertices++;return this;}public com.mojang.blaze3d.vertex.VertexConsumer setColor(int r,int g,int b,int a){return this;}public com.mojang.blaze3d.vertex.VertexConsumer setUv(float u,float v){return this;}public com.mojang.blaze3d.vertex.VertexConsumer setUv1(int u,int v){return this;}public com.mojang.blaze3d.vertex.VertexConsumer setUv2(int u,int v){return this;}public com.mojang.blaze3d.vertex.VertexConsumer setNormal(float x,float y,float z){return this;}}
 private static void carriedTray(Minecraft m,NativeNavigationTableEntity source){var projected=com.vandorlabs.neoforge.transfer.NativeSnapshotAppearance.project(source.getBlockState(),source.getUpdateTag(m.level.registryAccess()),m.level.registryAccess());var empty=projected.copy();empty.remove("NavigationModule");var sink=new Sink();var bare=(NativeNavigationTableEntity)com.vandorlabs.neoforge.transfer.client.NativeSnapshotPalette.build(m.level,source.getBlockPos(),source.getBlockState(),empty,1024*1024).tile();need(bare.publicVisual()&&!bare.mutable(),"unpublished public tray is read-only");m.getBlockEntityRenderDispatcher().getRenderer(bare).render(bare,0,new com.mojang.blaze3d.vertex.PoseStack(),layer->sink,0xf000f0,net.minecraft.client.renderer.texture.OverlayTexture.NO_OVERLAY);int emptyCount=sink.vertices;var full=(NativeNavigationTableEntity)com.vandorlabs.neoforge.transfer.client.NativeSnapshotPalette.build(m.level,source.getBlockPos(),source.getBlockState(),projected,1024*1024).tile();need(!full.moduleStack().isEmpty()&&NativeNavigationModuleData.count(full.moduleStack())>0,"carried tray resolves bounded module display without world inventory lookup");m.getBlockEntityRenderDispatcher().getRenderer(full).render(full,0,new com.mojang.blaze3d.vertex.PoseStack(),layer->sink,0xf000f0,net.minecraft.client.renderer.texture.OverlayTexture.NO_OVERLAY);need(sink.vertices-emptyCount>emptyCount&&emptyCount>0,"actual unpublished BER emits cassette beyond empty bay frame");System.out.println("[vandorlabs][navigation-client] carried-tray PASS emptyVertices="+emptyCount+" fullVertices="+(sink.vertices-emptyCount)+" publicOnly/readOnly/selfLookup");}
